const H = this.helpers;
const APPS = [
  { id: 'com.netlissbrasil.pro', nome: 'Netliss' },
  { id: 'com.easyconect.pro', nome: 'Easy Conect' },
  { id: 'com.dragonnet.pro', nome: 'DragonNet' },
];
const espera = ms => new Promise(r => setTimeout(r, ms));
const pega = async (app) => {
  let tok = null; const out = [];
  for (let p = 0; p < 4; p++) {
    const inner = JSON.stringify([null, null, [2, 2, [100, null, tok], null, []], [app, 7]]);
    const freq = JSON.stringify([[['UsvDTd', inner, null, 'generic']]]);
    let t = '';
    for (let k = 1; k <= 3; k++) {
      try {
        t = await H.httpRequest({ method: 'POST', url: 'https://play.google.com/_/PlayStoreUi/data/batchexecute?rpcids=UsvDTd&hl=pt_BR&gl=BR', headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' }, body: 'f.req=' + encodeURIComponent(freq), json: false, timeout: 30000 });
        break;
      } catch (e) { if (k === 3) throw e; await espera(3000 * k); }
    }
    const line = String(t).split('\n').find(l => l.includes('"UsvDTd"'));
    if (!line) break;
    const arr = JSON.parse(line);
    if (!arr[0][2]) break;
    const j = JSON.parse(arr[0][2]);
    for (const x of (j[0] || [])) out.push({ id: x[0], nome: (x[1] && x[1][0]) || '', nota: x[2], texto: String(x[4] || '').replace(/\s+/g, ' ').trim(), ts: (x[5] && x[5][0]) ? x[5][0] * 1000 : 0 });
    tok = j[1] && j[1][1];
    if (!tok) break;
  }
  return out;
};
const agora = Date.now(); const DIA = 86400000;
const dt = ts => new Date(ts).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const p2 = n => String(n).padStart(2, '0');
const media = l => l.length ? (l.reduce((a, x) => a + x.nota, 0) / l.length).toFixed(1).replace('.', ',') : '-';
const dados = {}; const erros = [];
for (const a of APPS) { try { dados[a.nome] = await pega(a.id); } catch (e) { dados[a.nome] = []; erros.push(a.nome + ': ' + e.message); } }

// 01) alerta no Telegram: avaliações novas da Netliss nas últimas 24h
const novas = (dados['Netliss'] || []).filter(x => x.ts >= agora - DIA);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let alerta = '';
if (novas.length) {
  alerta = '⭐ <b>Avaliações novas da Netliss na Play Store (' + p2(novas.length) + ')</b>\n\n' + novas.map(x => (x.nota <= 3 ? '⚠️ ' : '') + '★'.repeat(x.nota) + ' <b>' + esc(x.nome) + '</b>: ' + esc(x.texto.slice(0, 400))).join('\n\n');
  if (novas.some(x => x.nota <= 3)) alerta += '\n\n⚠️ Tem avaliação baixa: vale responder na Play Console hoje (resposta educada, oferecendo ajuda pela Liss no site).';
}

// 02) toda segunda-feira: comparativo com IA
const dow = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })).getDay();
const placar = APPS.map(a => {
  const l = dados[a.nome] || []; const r30 = l.filter(x => x.ts >= agora - 30 * DIA); const r90 = l.filter(x => x.ts >= agora - 90 * DIA);
  return a.nome + ': ' + p2(l.length) + ' avaliações lidas (média ' + media(l) + '); últimos 30 dias: ' + p2(r30.length) + ' (média ' + media(r30) + '); últimos 90 dias: ' + p2(r90.length) + ' (média ' + media(r90) + ', ' + p2(r90.filter(x => x.nota <= 2).length) + ' notas 01 ou 02)';
}).join('\n');
const textos = APPS.map(a => '### ' + a.nome + '\n' + (dados[a.nome] || []).filter(x => x.ts >= agora - 400 * DIA && x.texto).map(x => dt(x.ts) + ' | ' + x.nota + ' estrelas | ' + x.texto.slice(0, 500)).join('\n')).join('\n\n').slice(0, 60000);
const pedido = {
  model: 'claude-sonnet-5-5', max_tokens: 8000, thinking: { type: 'adaptive' }, output_config: { effort: 'low' },
  system: 'Voce e a gerente de marketing da Netliss (app de internet ilimitada para Android) e escreve para o dono, o Jean, um comparativo semanal das avaliacoes reais da Play Store: Netliss x Easy Conect x DragonNet (concorrentes diretos). Escreva em portugues do Brasil, simples, direto, como quem conversa. Numeros sempre com dois digitos (01, 02, 03). Use exatamente estas secoes, cada uma comecando com "## ": "## Placar", "## O que elogiam na Netliss", "## Do que reclamam da Netliss", "## Onde os concorrentes falham (oportunidade para nos)", "## O que fazer esta semana". Em cada secao, frases curtas e itens com "- ". Cite trechos reais curtos entre aspas quando ajudar. Nunca invente avaliacao nem numero: use so os dados recebidos. Em "O que fazer esta semana", no maximo 03 acoes praticas, ligadas a vender mais (site, anuncios, atendimento da Liss ou resposta as avaliacoes). Sem texto antes ou depois das secoes.',
  messages: [{ role: 'user', content: 'PLACAR (dados do sistema):\n' + placar + '\n\nAVALIACOES DOS ULTIMOS 120 DIAS:\n' + textos }],
};
return [{ json: { alerta, tem_alerta: !!alerta, segunda: dow === 1, pedido, placar, erros: erros.join(' | ') } }];

const r = $input.first().json; const base = $('Ler avaliações').first().json;
let txt = ''; try { txt = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim(); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const S = 'font-family:Arial,sans-serif;font-size:15px;line-height:1.6;color:#222;margin:6px 0';
const corpo = txt ? txt.split('\n').map(l => l.trim()).filter(Boolean).map(l => l.startsWith('## ') ? '<h3 style="font-family:Arial,sans-serif;margin:26px 0 8px;color:#0b2a1a;border-bottom:1px solid #dde;padding-bottom:4px">' + esc(l.slice(3)) + '</h3>' : (l.startsWith('- ') ? '<p style="' + S + ';margin-left:14px">• ' + esc(l.slice(2)) + '</p>' : '<p style="' + S + '">' + esc(l) + '</p>')).join('') : '<p style="' + S + '">A IA não conseguiu escrever o comparativo hoje.</p>';
const aviso = base.erros ? '<p style="' + S + ';color:#a00">⚠️ Não consegui ler todas as avaliações: ' + esc(base.erros) + '</p>' : '';
const html = '<div style="max-width:900px;font-family:Arial,sans-serif"><h2 style="margin:0 0 4px">Play Store: Netliss x concorrentes</h2><p style="color:#666;margin:0 0 10px">Avaliações reais, lidas hoje</p>' + aviso + corpo + '<h3 style="font-family:Arial,sans-serif;margin:26px 0 8px;color:#0b2a1a;border-bottom:1px solid #dde;padding-bottom:4px">Números do sistema</h3>' + base.placar.split('\n').map(l => '<p style="' + S + '">' + esc(l) + '</p>').join('') + '</div>';
return [{ json: { html, assunto: 'Netliss | Play Store: Netliss x concorrentes (' + new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }).slice(0, 5) + ')' } }];
